// Practical closures: once(), a private counter, and the loop fix
function once(fn) {
  let called = false, result;
  return function (...args) {
    if (!called) { called = true; result = fn.apply(this, args); }
    return result;                      // later calls return the first result
  };
}
const init = once(() => { console.log("initialising"); return 42; });
init(); init();                          // logs once

// Rate limiter: state held in the closure, not in globals
function makeLimiter(max, windowMs) {
  const hits = [];
  return function allow(now = Date.now()) {
    while (hits.length && hits[0] <= now - windowMs) hits.shift();
    if (hits.length >= max) return false;
    hits.push(now);
    return true;
  };
}
const limit = makeLimiter(3, 1000);
console.log([1, 2, 3, 4].map(() => limit()));   // [true, true, true, false]

// Typed closure: a counter factory whose state cannot be touched from outside
function createCounter(start = 0) {
  let n = start;
  return { inc: (by = 1) => (n += by), reset: () => { n = start; }, get value() { return n; } } as const;
}
const c = createCounter(10);
c.inc(5);
console.log(c.value);   // 15

// Re-implementing new, bind, and Object.create to prove you understand them
function myNew(Ctor, ...args) {
  const obj = Object.create(Ctor.prototype);        // 1 + 2: new object linked to Ctor.prototype
  const result = Ctor.apply(obj, args);              // 3: run constructor with this = obj
  return result !== null && (typeof result === "object" || typeof result === "function") ? result : obj; // 4
}

Function.prototype.myBind = function (thisArg, ...preset) {
  const fn = this;
  return function bound(...args) {
    // if called with new, ignore thisArg (like the real bind)
    return fn.apply(new.target ? this : thisArg, [...preset, ...args]);
  };
};

// Safe dictionary: no inherited keys, immune to "constructor"/"__proto__" collisions
const counts = Object.create(null);
for (const w of ["constructor", "a", "a"]) counts[w] = (counts[w] ?? 0) + 1;
console.log(counts);   // { constructor: 1, a: 2 }

// Class with private fields, readonly props and an abstract template method
abstract class Report {
  readonly createdAt = new Date();
  protected abstract title(): string;
  protected abstract rows(): string[];
  render(): string {                         // Template Method: fixed skeleton, subclasses fill the steps
    return [this.title(), ...this.rows().map((r) => `- ${r}`)].join("\n");
  }
}
class SalesReport extends Report {
  #total = 0;
  constructor(private readonly items: { name: string; amount: number }[]) { super(); this.#total = items.reduce((s, i) => s + i.amount, 0); }
  protected title() { return `Sales (${this.#total})`; }
  protected rows() { return this.items.map((i) => `${i.name}: ${i.amount}`); }
}

// Surprises to be able to explain, and safe replacements
console.log(0.1 + 0.2 === 0.3);                       // false -> compare with a tolerance or use integer cents
console.log(Math.abs(0.1 + 0.2 - 0.3) < Number.EPSILON); // true
console.log([] == false, [] === false);                // true false
console.log(null == undefined, null === undefined);    // true false
console.log(typeof null, Array.isArray([]));           // "object" true
console.log(Number.isNaN("abc"), isNaN("abc"));        // false true (global isNaN coerces: avoid)
console.log(0 || 5, 0 ?? 5);                            // 5 0

// Deep clone and frequency count with Map
const original = { d: new Date(), nested: { list: [1, 2, 3] } };
const copy = structuredClone(original);
copy.nested.list.push(4);
console.log(original.nested.list.length);               // 3: independent

const freq = new Map();
for (const w of "to be or not to be".split(" ")) freq.set(w, (freq.get(w) ?? 0) + 1);
console.log([...freq]);                                 // [["to",2],["be",2],["or",1],["not",1]]

// A safe typeof-like helper
const kind = (x) => Object.prototype.toString.call(x).slice(8, -1).toLowerCase();
console.log(kind(null), kind([]), kind(new Map()), kind(/a/));   // null array map regexp

// TypeScript helps catch coercion bugs: no implicit string + number mixing, strict null checks
function total(a: number, b: number): number { return a + b; }
// total("1", 2);             // compile error: Argument of type 'string' is not assignable to 'number'

function getCity(user?: { address?: { city?: string } }): string {
  return user?.address?.city ?? "unknown";     // ?? only falls back on null/undefined
}
